Definition fbb_ok (FB : fbv) (FBB : list block) : Prop :=
  (FB = FB_empty /\ FBB = []) \/ (FB <> FB_empty /\ exists pf, FBB = [(pf, fb_begin FB, fb_cap FB)]).

