Definition rs_frames (m : mem) (sp : word) (j8 : list byte) (t1c t2c : list cell) (s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra : word) (fr0 : list word) : Prop :=
  rs_frame m sp j8 t1c t2c /\ rw_cells rsegs m (bv_unsigned sp + -88) (map C8 (rs_sv s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra))
  /\ rw_cells rsegs m (bv_unsigned sp) (map C8 fr0) /\ length fr0 = 8%nat.

(* [comment removed for export] *)
Definition rs_core (C : rsc) (sp : word) (s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra : word) (fr0 : list word) (w : rsw) (E : ecv) (tot : Z) (m : mem)
    (j8 : list byte) (t1c t2c : list cell) : Prop :=
  RWm C w E m /\ RWp C w /\ stk rsegs m (c_lo C) (bv_unsigned sp + -144)
  /\ rs_frames m sp j8 t1c t2c s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra fr0
  /\ xpres (c_LBin C) (c_P C) (sro_X (c_P C) (c_stb C)) (c_m0 C) m
  /\ 0 <= tot /\ tot + zlength (w_fds w) + zlength (w_sds w) <= c_N C
  /\ w_nr w <= c_N C - zlength (w_sds w).

(* [comment removed for export] *)
Definition rs_at_put (C : rsc) (sp : word) (s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra : word) (fr0 : list word) (M0 : Z) (w : rsw) (cf : config) : Prop :=
  exists (t0 t1 t2 a4 a5 a6 a7 s5x s6x s7x s9x t3 t4 t5 t6 : word) (m : mem) (E : ecv) (tot : Z) (j8 : list byte) (t1c t2c : list cell),
    cfg_ms cf = rs_ms P_BP_PUT (wz RS_PUTRET) sp (c_gp C) (c_tp C) t0 t1 t2 tot (c_P C) (wz (c_P C)) (wz (fb_in (w_FB w))) (wz (fb_size (w_FB w))) (wz (c_P C + O_H_EC))
                      a4 a5 a6 a7 s5x s6x s7x s9x (c_s10 C) (c_s11 C) t3 t4 t5 t6 (c_F C) (c_fc C) m
    /\ 1 <= fb_size (w_FB w) /\ pc_state (ps_c (w_d w)) <> 11
    /\ hs_KREL H (ps_st (w_d w)) (cfg_model cf) /\ hs_MPRES H (c_mo0 C) (cfg_model cf)
    /\ rs_core C sp s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra fr0 w E tot m j8 t1c t2c
    /\ wM (c_N C) w <= M0.

(* [comment removed for export] *)
Definition rs_at_doread (C : rsc) (sp : word) (s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra : word) (fr0 : list word) (M0 : Z) (w : rsw) (cf : config) : Prop :=
  exists (rax t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s5x s6x s7x s9x t3 t4 t5 t6 : word) (m : mem) (E : ecv) (tot : Z) (j8 : list byte) (t1c t2c : list cell),
