(* [comment removed for export] *)
Definition rs_done (C : rsc) (sp : word) (s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra : word) (fr0 : list word) (M0 : Z) (cf : config) : Prop :=
  exists (t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (m : mem) (w : rsw) (E : ecv) (tot : Z),
    cfg_ms cf = MS (mkR ra sp (c_gp C) (c_tp C) t0 t1 t2 s0v s1v (wz tot) a1 a2 a3 a4 a5 a6 a7 s2v s3v s4v s5v s6v s7v s8v s9v (c_s10 C) (c_s11 C) t3 t4 t5 t6)
                   (c_F C) (ret_pc ra) (c_fc C) None m (seg_rom rsegs)
    /\ hs_KREL H (ps_st (w_d w)) (cfg_model cf) /\ hs_MPRES H (c_mo0 C) (cfg_model cf)
    /\ RWm C w E m /\ RWp C w /\ stk rsegs m (c_lo C) (bv_unsigned sp)
    /\ rw_cells rsegs m (bv_unsigned sp) (map C8 fr0)
    /\ xpres (c_LBin C) (c_P C) (sro_X (c_P C) (c_stb C)) (c_m0 C) m
    /\ 0 <= tot /\ tot + zlength (w_fds w) + zlength (w_sds w) <= c_N C
    /\ ec_ok E /\ (E = EC_clear \/ http_fail E)
    /\ wM (c_N C) w <= M0
    /\ (E = EC_clear -> pc_state (ps_c (w_d w)) <> 11 -> wM (c_N C) w < M0 /\ w_nr w <= c_N C - zlength (w_sds w)).


